;(function(){
  try {
    if (typeof window !== 'undefined' && !window._ccxSpreadZoomAndFullscreenPatchedV380) {
      window._ccxSpreadZoomAndFullscreenPatchedV380 = true;
      window.prewarmNeighborBookPages = async function(centerPage, step) {
        if (!window.pdfDoc) return;
        const targets = [];
        for (let offset = 1; offset <= 2; offset++) {
          const pLeft = centerPage + offset * step;
          if (pLeft >= 1 && pLeft <= window.totalPdfPages) targets.push(pLeft);
          if (step === 2 && pLeft + 1 <= window.totalPdfPages) targets.push(pLeft + 1);
        }
        const dummy = document.createElement('canvas');
        for (const p of targets) {
          if (window.renderedPages && window.renderedPages.has(p)) continue;
          try { await window.renderSinglePdfPage(p, dummy, true); } catch (e) {}
        }
      };
    }
  } catch (e) {}
})();
